export interface InitialIdentityCard {
  cardId: string;
  role: Role;
}

export interface InitialIdentityDeal {
  readonly initialRoles: readonly Role[];
  readonly candidateCounts: ReadonlyMap<Role, number>;
  readonly hands: Map<number, InitialIdentityCard>;
  readonly reserve: [InitialIdentityCard, InitialIdentityCard];
  status: InitialIdentitySetupStatus;
  selection: { actorId: number; slot: InitialIdentitySlot | null; role: Role } | null;
}

export const INITIAL_IDENTITY_POLICIES = Object.freeze({
  thief: "lui_meme_thief_two_extra_villagers_v1",
  shapeshifter: "awa_netease_shapeshifter_two_extra_villagers_v1",
} as const);

export function readInitialIdentityCard(value: unknown): InitialIdentityCard | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const keys = Reflect.ownKeys(value);
  if (keys.length !== 2 || !keys.every((k) => k === "cardId" || k === "role")) return null;
  const cardId = field(value, "cardId"),
    role = field(value, "role");
  return typeof cardId === "string" &&
    /^deal:[0-9]+$/.test(cardId) &&
    Object.values(Role).includes(role as Role)
    ? { cardId, role: role as Role }
    : null;
}

export function installInitialIdentityDeal(
  world: World,
  roles: readonly Role[],
  playerIds: readonly number[],
  kind: InitialIdentityKind = "thief",
): void {
  if (kind !== "thief" && kind !== "shapeshifter") throw new Error("initial_identity_kind_invalid");
  if (owned.has(world) || roles.length !== playerIds.length + 2)
    throw new Error(`${kind}_initial_deal_invalid`);
  const cards = roles.map((role, i) => ({ cardId: `deal:${i}`, role }));
  const initialCards = Object.freeze(cards.map((card) => Object.freeze({ ...card }))),
    initialRoles = Object.freeze([...roles]);
  const candidateCounts = new Map<Role, number>();
  for (const role of roles) candidateCounts.set(role, (candidateCounts.get(role) ?? 0) + 1);
  const hands = new Map(playerIds.map((id, i) => [id, cards[i]!])),
    reserve: [InitialIdentityCard, InitialIdentityCard] = [
      cards[playerIds.length]!,
      cards[playerIds.length + 1]!,
    ];
  const deal: InitialIdentityDeal = {
    initialRoles,
    candidateCounts,
    hands,
    reserve,
    status: "pending",
    selection: null,
  };
  const players = playerIds.map((id) => {
    const role = world.getComponent(id, COMPONENT.Role)!,
      life = captureNightLife(world, id)!;
    return {
      id,
      role,
      roleId: role.role,
      camp: role.camp,
      state: role.privateState,
      life,
      campComponent: world.getComponent(id, COMPONENT.Camp),
      victory: world.getComponent(id, COMPONENT.Victory),
      victoryJson: JSON.stringify(copyEventData(world.getComponent(id, COMPONENT.Victory))),
    };
  });
  owned.set(world, {
    kind,
    deal,
    cards: Object.freeze([...cards]),
    initialCards,
    playerIds: Object.freeze([...playerIds]),
    hands,
    reserve,
    status: "pending",
    selection: null,
    selectionSnapshot: null,
    players,
  });
}

export function initialIdentityKind(world: World): InitialIdentityKind | undefined {
  return owned.get(world)?.kind;
}

export function initialIdentityStock(world: World): InitialIdentityDeal | undefined {
  return owned.get(world)?.deal;
}

export function initialIdentityDeal(world: World): readonly Role[] | undefined {
  return owned.get(world)?.initialCards.map((card) => card.role);
}

export function initialIdentityCandidateCounts(
  world: World,
): ReadonlyMap<Role, number> | undefined {
  const owner = owned.get(world);
  if (!owner) return;
  const counts = new Map<Role, number>();
  for (const card of owner.initialCards) counts.set(card.role, (counts.get(card.role) ?? 0) + 1);
  return counts;
}

export function initialIdentitySetupStatus(world: World): InitialIdentitySetupStatus | undefined {
  return owned.get(world)?.status;
}

export function hasActiveInitialIdentitySetup(world: World): boolean {
  return active.has(world);
}

export function initialIdentitySetupReady(world: World): boolean {
  return !owned.has(world) || owned.get(world)!.status === "complete";
}

export function pendingInitialIdentityDealValid(world: World): boolean {
  const o = owned.get(world);
  if (
    !o ||
    o.status !== "pending" ||
    field(o.deal, "hands") !== o.hands ||
    field(o.deal, "reserve") !== o.reserve
  )
    return false;
  if (
    world.entityIds().length !== o.playerIds.length ||
    !o.players.every(
      (p) =>
        livingNightLife(world, p.life) &&
        world.getComponent(p.id, COMPONENT.Role) === p.role &&
        field(p.role, "role") === p.roleId &&
        field(p.role, "camp") === p.camp &&
        field(p.role, "privateState") === p.state &&
        world.getComponent(p.id, COMPONENT.Camp) === p.campComponent &&
        field(p.campComponent, "camp") === p.camp &&
        world.getComponent(p.id, COMPONENT.Victory) === p.victory,
    )
  )
    return false;
  try {
    if (o.players.some((p) => JSON.stringify(copyEventData(p.victory)) !== p.victoryJson))
      return false;
  } catch {
    return false;
  }
  const size = Object.getOwnPropertyDescriptor(Map.prototype, "size")!.get!.call(o.hands);
  if (size !== o.playerIds.length || o.reserve.length !== 2) return false;
  for (let i = 0; i < o.cards.length; i++) {
    const card = o.cards[i]!,
      data = readInitialIdentityCard(card),
      original = o.initialCards[i]!;
    if (!data || data.cardId !== original.cardId || data.role !== original.role) return false;
    const current =
      i < o.playerIds.length
        ? Map.prototype.get.call(o.hands, o.playerIds[i]!)
        : readSlot(o.reserve, (i - o.playerIds.length) as InitialIdentitySlot);
    if (current !== card) return false;
  }
  return true;
}

export function openInitialIdentitySetup(world: World): InitialIdentityDeal {
  const o = owned.get(world);
  if (!o || o.status !== "pending" || opened.has(world) || active.has(world))
    throw unavailable(world, "setup_unavailable");
  opened.add(world);
  active.add(world);
  return o.deal;
}

export function closeInitialIdentitySetup(
  world: World,
  status: Exclude<InitialIdentitySetupStatus, "pending">,
): void {
  active.delete(world);
  const o = owned.get(world);
  if (!o) return;
  o.status = status;
  const d = Object.getOwnPropertyDescriptor(o.deal, "status");
  if (d && Object.hasOwn(d, "value") && d.writable)
    try {
      Object.defineProperty(o.deal, "status", { ...d, value: status });
    } catch {
      /* Authority closes even with corrupted storage. */
    }
}

export function selectInitialIdentityCard(
  world: World,
  actorId: number,
  slot: InitialIdentitySlot | null,
): Role {
  const o = owned.get(world);
  if (!o || !hasActiveInitialIdentitySetup(world) || !pendingInitialIdentityDealValid(world))
    throw unavailable(world, "selection_unavailable");
  const original = Map.prototype.get.call(o.hands, actorId) as InitialIdentityCard;
  if (
    o.kind === "shapeshifter" &&
    (slot === null ||
      (slot !== 0 && slot !== 1) ||
      readInitialIdentityCard(original)?.role !== Role.Shapeshifter ||
      (o.reserve.some((card) => readInitialIdentityCard(card)?.role === Role.Wolf) &&
        readInitialIdentityCard(readSlot(o.reserve, slot))?.role !== Role.Wolf))
  )
    throw unavailable(world, "selection_invalid");
  const chosen = slot === null ? original : (readSlot(o.reserve, slot) as InitialIdentityCard);
  if (slot !== null) {
    Map.prototype.set.call(o.hands, actorId, chosen);
    o.reserve[slot] = original;
  }
  const selection = { actorId, slot, role: chosen.role };
  o.selection = selection;
  o.selectionSnapshot = Object.freeze({ ...selection });
  o.deal.selection = selection;
  return chosen.role;
}

export function projectInitialIdentitySetup(world: World) {
  const o = owned.get(world);
  if (!o) return;
  if (
    field(o.deal, "hands") !== o.hands ||
    field(o.deal, "reserve") !== o.reserve ||
    o.reserve.length !== 2
  )
    return;
  const hands = o.playerIds.map((actorId) => ({
      actorId,
      card: Map.prototype.get.call(o.hands, actorId) as unknown,
    })),
    reserves = [readSlot(o.reserve, 0), readSlot(o.reserve, 1)];
  const raw = [...hands.map((row) => row.card), ...reserves];
  if (
    raw.length !== o.cards.length ||
    new Set(raw).size !== o.cards.length ||
    raw.some((card) => !o.cards.includes(card as InitialIdentityCard))
  )
    return;
  const data = raw.map(readInitialIdentityCard);
  if (data.some((card) => !card)) return;
  for (const card of data)
    if (!o.initialCards.some((c) => c.cardId === card!.cardId && c.role === card!.role)) return;
  const selection = field(o.deal, "selection");
  if (selection !== o.selection) return;
  if (
    selection &&
    (!o.selectionSnapshot ||
      Reflect.ownKeys(selection as object).length !== 3 ||
      ["actorId", "slot", "role"].some(
        (key) => field(selection, key) !== field(o.selectionSnapshot, key),
      ))
  )
    return;
  const selected = o.selectionSnapshot;
  const selectedIndex = selected ? o.playerIds.indexOf(selected.actorId) : -1;
  for (let i = 0; i < o.playerIds.length; i++) {
    const expected =
      selectedIndex === i && selected?.slot !== null && selected?.slot !== undefined
        ? o.cards[o.playerIds.length + selected.slot]
        : o.cards[i];
    if (raw[i] !== expected) return;
  }
  for (const slot of [0, 1] as const) {
    const expected =
      selected?.slot === slot ? o.cards[selectedIndex] : o.cards[o.playerIds.length + slot];
    if (reserves[slot] !== expected) return;
  }
  return {
    policy: INITIAL_IDENTITY_POLICIES[o.kind],
    status: o.status,
    hands: hands.map((row, i) => ({ actorId: row.actorId, ...data[i]! })),
    reserve: data.slice(hands.length) as [InitialIdentityCard, InitialIdentityCard],
    selection: o.selectionSnapshot ? { ...o.selectionSnapshot } : null,
  };
}

export function hasActiveInitialIdentityNight(world: World): boolean {
  return activeNights.has(world);
}

export function hasInitialIdentityNightCommit(world: World, day: number): boolean {
  return committedNights.get(world)?.has(day) === true;
}

export function openInitialIdentityNight(world: World, day: number): () => void {
  if (!owned.has(world)) return () => {};
  if (
    !initialIdentitySetupReady(world) ||
    hasActiveInitialIdentitySetup(world) ||
    activeNights.has(world) ||
    committedNights.get(world)?.has(day)
  )
    throw unavailable(world, "night_reentry_or_unready");
  let days = committedNights.get(world);
  if (!days) {
    days = new Set();
    committedNights.set(world, days);
  }
  days.add(day);
  activeNights.add(world);
  return () => {
    activeNights.delete(world);
  };
}

export {
  hasActiveInitialIdentitySetup,
  hasActiveInitialIdentityNight,
  hasInitialIdentityNightCommit,
  initialIdentityKind,
  initialIdentitySetupReady,
  openInitialIdentityNight,
} from "./deal";

export interface InitialIdentityScope {
  world: World;
  kind: InitialIdentityKind;
  actorId: number;
  deal: InitialIdentityDeal;
  reserve: InitialIdentityDeal["reserve"];
  hands: Map<number, InitialIdentityCard>;
  cards: readonly [CardScope, CardScope];
  originalHand: InitialIdentityCard;
  participants: readonly DebateParticipant[];
  actor: DebateParticipant;
  state: InitialIdentityState;
  camp: CampComponent;
  victory: VictoryComponent;
  victoryJson: string;
  config: ReadonlyBoardConfig;
  configJson: string;
  isCurrent: () => boolean;
  required: boolean;
  allowedSlots: readonly InitialIdentitySlot[];
}

export function authorizedInitialIdentityScope(
  world: World,
  actorId: number,
  day: number | undefined,
  phase: Phase,
  scope: object | undefined,
  kind: InitialIdentityKind,
): InitialIdentityScope | null {
  const active = scopes.get(world);
  return active &&
    active === scope &&
    active.kind === kind &&
    actorId === active.actorId &&
    day === 1 &&
    phase === Phase.Night &&
    sameInitialIdentityScope(active)
    ? active
    : null;
}

export function bindInitialIdentityRequest(world: World, request: ActionRequest): void {
  requestLease.bind(world, request);
}

export function initialIdentityRequestScope(
  world: World,
  request: ActionRequest,
): InitialIdentityScope | undefined {
  return requestLease.scope(world, request);
}

export function initialIdentityRequestChoices(
  world: World,
  actorId: number,
  kind: InitialIdentityKind,
) {
  const scope = scopes.get(world);
  if (
    !scope ||
    scope.kind !== kind ||
    scope.actorId !== actorId ||
    !sameInitialIdentityScope(scope)
  )
    return undefined;
  return {
    mustChoose: scope.required,
    allowedSlots: [...scope.allowedSlots],
    cards: scope.cards.map((card, slot) => ({
      slot: slot as InitialIdentitySlot,
      role: card.role,
    })),
  };
}

export class InitialIdentitySetupWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
    private readonly kind: InitialIdentityKind,
    /** 保存装配端对象；原创建点才读取构造器，不提前捕获类或共享已创建的工厂。 */
    private readonly construction: { readonly requestFactory: ActionRequestFactoryConstructorPort },
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    provider: ActionProvider,
    day: number,
    isCurrent: () => boolean,
  ): Promise<boolean> {
    if (initialIdentityKind(this.world) !== this.kind) return true;
    if (hasActiveInitialIdentitySetup(this.world)) throw new Error(`${this.kind}_setup_reentry`);
    if (initialIdentitySetupReady(this.world)) return true;
    if (day !== 1 || initialIdentitySetupStatus(this.world) !== "pending" || !isCurrent())
      throw new Error(`${this.kind}_setup_unavailable`);
    const deal = openInitialIdentitySetup(this.world);
    let status: "complete" | "cancelled" | "failed" = "failed";
    let delivery: RequestLeaseTurn | undefined, failed = false;
    try {
      if (!pendingInitialIdentityDealValid(this.world)) {
        status = "cancelled";
        return false;
      }
      const actorIds = this.world
        .getAliveEntityIds()
        .filter(
          (id) =>
            this.world.getComponent(id, COMPONENT.Role)?.role === initialIdentityRole(this.kind),
        );
      if (actorIds.length === 0) {
        status = "complete";
        return true;
      }
      if (actorIds.length !== 1) throw new Error(`${this.kind}_actor_invalid`);
      const actorId = actorIds[0]!,
        actor = captureDebateParticipant(this.world, actorId),
        state = getInitialIdentityState(actor?.role, this.kind),
        camp = this.world.getComponent(actorId, COMPONENT.Camp),
        victory = this.world.getComponent(actorId, COMPONENT.Victory);
      const cards = deal.reserve.map((card) => {
        const data = readInitialIdentityCard(card);
        return data ? { card, ...data } : null;
      });
      const configJson = frozenJson(config),
        victoryJson = frozenJson(victory);
      if (
        !actor ||
        actor.camp !== Camp.Good ||
        !state ||
        !camp ||
        !victory ||
        cards.some((card) => !card) ||
        configJson === null ||
        victoryJson === null
      ) {
        status = "cancelled";
        return false;
      }
      const participants = this.world
        .entityIds()
        .map((id) => captureDebateParticipant(this.world, id));
      if (participants.some((p) => !p)) {
        status = "cancelled";
        return false;
      }
      const scope: InitialIdentityScope = {
        world: this.world,
        kind: this.kind,
        actorId,
        deal,
        reserve: deal.reserve,
        hands: deal.hands,
        cards: cards as [CardScope, CardScope],
        originalHand: deal.hands.get(actorId)!,
        participants: participants as DebateParticipant[],
        actor,
        state,
        camp,
        victory,
        victoryJson,
        config,
        configJson,
        isCurrent,
        required: initialIdentityChoiceRule(
          this.kind,
          cards.map((c) => c!.role),
        ).mustChoose,
        allowedSlots: initialIdentityChoiceRule(
          this.kind,
          cards.map((c) => c!.role),
        ).allowedSlots,
      };
      scopes.set(this.world, scope);
      if (!sameInitialIdentityScope(scope)) {
        status = "cancelled";
        return false;
      }
      // 原 scope 已安装并复验后才读取构造器；构造或 create 失败仍走下方原 finally 关闭。
      const request = new this.construction.requestFactory(this.world, this.events, 1).create({
        phase: Phase.Night,
        actorId,
        allowedTools: [initialIdentityTool(this.kind)],
        stage: this.kind,
        requiresAction: scope.required,
        summary: {
          key:
            this.kind === "shapeshifter"
              ? "turn.shapeshifter.required"
              : scope.required
                ? "turn.thief.required"
                : "turn.thief.optional",
        },
        context: { allow_fallback: false, action_failure_policy: "error" },
      });
      // 绑定表不抢 guard；真实窗口在完整 create 返回后才打开自己的交付和完成身份。
      delivery = requestLease.openDelivery(this.world, request);
      if (!sameInitialIdentityScope(scope) || delivery?.current() !== true) {
        status = "cancelled";
        return false;
      }
      const call = await provider.getAction(request);
      if (!sameInitialIdentityScope(scope) || delivery?.current() !== true) {
        status = "cancelled";
        return false;
      }
      let slot: InitialIdentitySlot | null = null;
      if (call === null) {
        if (scope.required) throw new Error(`${this.kind}_required_choice_missing`);
      } else {
        const choiceCall = readInitialIdentityTool(call, this.kind);
        if (!choiceCall) throw new Error(`${this.kind}_choice_invalid`);
        const valid = this.gateway.validateAndSanitize(this.world, actorId, choiceCall, {
          phase: Phase.Night,
          day: 1,
          ...(this.kind === "thief" ? { thiefScope: scope } : { shapeshifterScope: scope }),
        });
        if (!sameInitialIdentityScope(scope) || delivery.current() !== true) {
          status = "cancelled";
          return false;
        }
        if (!valid.ok || !scope.allowedSlots.includes(choiceCall.args.slot))
          throw new Error(`${this.kind}_choice_invalid`);
        slot = choiceCall.args.slot;
      }
      const chosen = slot === null ? null : scope.cards[slot].card;
      const catalog = getDefaultRoleCatalog();
      const newRole = chosen
        ? createRoleComponent(chosen.role, catalog.getCamp(chosen.role), this.world.locale)
        : null;
      if (newRole)
        catalog.applyRuntime(newRole, {
          boardConfig: config,
          locale: this.world.locale,
          world: this.world,
        });
      const newCamp = newRole ? createCampComponent(newRole.camp, this.world.locale) : null;
      const newVictory = newRole
        ? createVictoryComponent([{ kind: "faction", faction: newRole.camp }])
        : null;
      if (!sameInitialIdentityScope(scope) || delivery.current() !== true) {
        status = "cancelled";
        return false;
      }
      // 物理交换与身份安装之间没有 await、Provider 回调或事件发表。
      if (chosen && slot !== null && newRole && newCamp && newVictory) {
        if (this.kind === "shapeshifter") {
          consumeShapeshifterState(state, slot);
        }
        selectInitialIdentityCard(this.world, actorId, slot);
        this.world.addComponent(actorId, COMPONENT.Role, newRole);
        this.world.addComponent(actorId, COMPONENT.Camp, newCamp);
        this.world.addComponent(actorId, COMPONENT.Victory, newVictory);
      } else {
        consumeRetainedInitialIdentityState(state);
        selectInitialIdentityCard(this.world, actorId, null);
      }
      status = "complete";
      closeInitialIdentitySetup(this.world, status);
      scopes.delete(this.world);
      // 物理换牌、全部组件安装与原关闭成功后才落 true；事实／通知晚抛不能再结算 false。
      delivery.complete();
      const data = {
        actorId,
        day: 1 as const,
        role: newRole?.role ?? initialIdentityRole(this.kind),
        camp: newRole?.camp ?? Camp.Good,
      };
      this.events.push(
        this.kind === "shapeshifter"
          ? {
              timestamp: Date.now(),
              type: "shapeshifter_identity_chosen",
              payload: {
                ...data,
                slot: slot!,
                policy: "awa_netease_shapeshifter_two_extra_villagers_v1",
              },
            }
          : {
              timestamp: Date.now(),
              type: "thief_identity_chosen",
              payload: { ...data, slot, policy: "lui_meme_thief_two_extra_villagers_v1" },
            },
      );
      return true;
    } catch (error) {
      failed = true;
      throw error;
    } finally {
      try {
      if (this.kind === "shapeshifter" && status !== "complete") {
        const original =
          scopes.get(this.world)?.state ??
          this.world
            .entityIds()
            .map((id) =>
              getInitialIdentityState(this.world.getComponent(id, COMPONENT.Role), this.kind),
            )
            .find(Boolean);
        cancelShapeshifterState(original);
      }
      scopes.delete(this.world);
      closeInitialIdentitySetup(this.world, status);
      } catch (error) {
        // 原 finally 的清理错误仍按旧 JS 优先于 body 错误；新 false 通知不得覆盖它。
        failed = true;
        throw error;
      } finally {
        if (failed) { try { delivery?.close(); } catch { /* 已有原错误时只完成关闭，保该错误。 */ } }
        else delivery?.close();
      }
    }
  }
}
